{
    "Description": "Cost management tools that help you to monitor and manage your AWS costs",
    "Parameters": {
        "BudgetLimit": {
            "Type": "Number",
            "Default": 100,
            "Description": "Enter your $USD threshold here (ex: 100)"
        },
        "BudgetNotify": {
            "Type": "String",
            "Default": "+61",
            "Description": "Specify where the notification should be sent (for SMS, specify the country code too, eg +61, and drop the leading 0)"
        },
        "BudgetNotifyMethod": {
            "Type": "String",
            "Default": "sms",
            "AllowedValues": [
                "sms",
                "email"
            ],
            "Description": "Specify the notification method: sms for text message, email for email"
        }
    },
    "Resources": {
        "BillingTopicKey1E94F9A8": {
            "Type": "AWS::KMS::Key",
            "Properties": {
                "KeyPolicy": {
                    "Statement": [
                        {
                            "Action": "kms:*",
                            "Effect": "Allow",
                            "Principal": {
                                "AWS": {
                                    "Fn::Join": [
                                        "",
                                        [
                                            "arn:aws:iam::",
                                            {
                                                "Ref": "AWS::AccountId"
                                            },
                                            ":root"
                                        ]
                                    ]
                                }
                            },
                            "Resource": "*"
                        }
                    ],
                    "Version": "2012-10-17"
                },
                "EnableKeyRotation": true,
                "Tags": [
                    {
                        "Key": "created-by",
                        "Value": "CostManagementStack"
                    }
                ]
            },
            "UpdateReplacePolicy": "Delete",
            "DeletionPolicy": "Delete",
            "Metadata": {
                "aws:cdk:path": "CostManagementStack/BillingTopicKey/Resource"
            }
        },
        "BillingTopicKeyAlias9604A58C": {
            "Type": "AWS::KMS::Alias",
            "Properties": {
                "AliasName": "alias/billing-topic-key",
                "TargetKeyId": {
                    "Fn::GetAtt": [
                        "BillingTopicKey1E94F9A8",
                        "Arn"
                    ]
                }
            },
            "Metadata": {
                "aws:cdk:path": "CostManagementStack/BillingTopicKey/Alias/Resource"
            }
        },
        "BillingSNSTopicDCB11227": {
            "Type": "AWS::SNS::Topic",
            "Properties": {
                "KmsMasterKeyId": {
                    "Fn::GetAtt": [
                        "BillingTopicKey1E94F9A8",
                        "Arn"
                    ]
                },
                "Tags": [
                    {
                        "Key": "created-by",
                        "Value": "CostManagementStack"
                    }
                ]
            },
            "Metadata": {
                "aws:cdk:path": "CostManagementStack/BillingSNSTopic/Resource"
            }
        },
        "BillingSNSPolicyD4686BD2": {
            "Type": "AWS::SNS::TopicPolicy",
            "Properties": {
                "PolicyDocument": {
                    "Statement": [
                        {
                            "Action": "sns:publish",
                            "Effect": "Allow",
                            "Principal": {
                                "Service": [
                                    "budgets.amazonaws.com",
                                    "cloudwatch.amazonaws.com"
                                ]
                            },
                            "Resource": {
                                "Ref": "BillingSNSTopicDCB11227"
                            }
                        }
                    ],
                    "Version": "2012-10-17"
                },
                "Topics": [
                    {
                        "Ref": "BillingSNSTopicDCB11227"
                    }
                ]
            },
            "Metadata": {
                "aws:cdk:path": "CostManagementStack/BillingSNSPolicy/Resource"
            }
        },
        "BillingSNSSubscription": {
            "Type": "AWS::SNS::Subscription",
            "Properties": {
                "Protocol": {
                    "Ref": "BudgetNotifyMethod"
                },
                "TopicArn": {
                    "Ref": "BillingSNSTopicDCB11227"
                },
                "Endpoint": {
                    "Ref": "BudgetNotify"
                }
            },
            "Metadata": {
                "aws:cdk:path": "CostManagementStack/BillingSNSSubscription"
            }
        },
        "Budget": {
            "Type": "AWS::Budgets::Budget",
            "Properties": {
                "Budget": {
                    "BudgetLimit": {
                        "Amount": {
                            "Ref": "BudgetLimit"
                        },
                        "Unit": "USD"
                    },
                    "BudgetName": "Budget",
                    "BudgetType": "COST",
                    "CostTypes": {
                        "IncludeCredit": false,
                        "IncludeDiscount": false,
                        "IncludeOtherSubscription": false,
                        "IncludeRecurring": false,
                        "IncludeRefund": false,
                        "IncludeSubscription": false,
                        "IncludeSupport": false,
                        "IncludeTax": false,
                        "IncludeUpfront": false,
                        "UseAmortized": false,
                        "UseBlended": false
                    },
                    "TimePeriod": {
                        "End": "1926864800",
                        "Start": "1225864800"
                    },
                    "TimeUnit": "MONTHLY"
                },
                "NotificationsWithSubscribers": [
                    {
                        "Notification": {
                            "ComparisonOperator": "GREATER_THAN",
                            "NotificationType": "ACTUAL",
                            "Threshold": 99,
                            "ThresholdType": "PERCENTAGE"
                        },
                        "Subscribers": [
                            {
                                "Address": {
                                    "Ref": "BillingSNSTopicDCB11227"
                                },
                                "SubscriptionType": "SNS"
                            }
                        ]
                    },
                    {
                        "Notification": {
                            "ComparisonOperator": "GREATER_THAN",
                            "NotificationType": "ACTUAL",
                            "Threshold": 80,
                            "ThresholdType": "PERCENTAGE"
                        },
                        "Subscribers": [
                            {
                                "Address": {
                                    "Ref": "BillingSNSTopicDCB11227"
                                },
                                "SubscriptionType": "SNS"
                            }
                        ]
                    }
                ]
            },
            "Metadata": {
                "aws:cdk:path": "CostManagementStack/Budget"
            }
        }
    }
}

{
 "Description": "Queue accounts for deletion with organizations:CloseAccount",
 "Resources": {
  "LogGroup": {
   "Properties": {
    "LogGroupName": {
     "Fn::Join": [
      "/",
      [
       "/aws/vendedlogs/states",
       {
        "Ref": "AWS::StackName"
       },
       {
        "Fn::Select": [
         2,
         {
          "Fn::Split": [
           "/",
           {
            "Ref": "AWS::StackId"
           }
          ]
         }
        ]
       }
      ]
     ]
    },
    "RetentionInDays": 365
   },
   "Type": "AWS::Logs::LogGroup"
  },
  "OrganizationsAccountClosureStateMachine": {
   "Properties": {
    "Definition": {
     "Comment": "Close Organizations accounts tagged for closure",
     "StartAt": "Set empty pagination token",
     "States": {
      "Additional pages?": {
       "Choices": [
        {
         "Next": "Done paginating",
         "StringEquals": "",
         "Variable": "$.PaginationToken"
        }
       ],
       "Default": "Find accounts tagged for closure",
       "Type": "Choice"
      },
      "Done paginating": {
       "Type": "Succeed"
      },
      "Find accounts tagged for closure": {
       "Next": "For each account tagged REQUESTED",
       "Parameters": {
        "PaginationToken.$": "$.PaginationToken",
        "ResourceTypeFilters": [
         "organizations:account"
        ],
        "TagFilters": [
         {
          "Key": "organizations:account-closure",
          "Values": [
           "REQUESTED"
          ]
         }
        ]
       },
       "Resource": "arn:aws:states:::aws-sdk:resourcegroupstaggingapi:getResources",
       "Type": "Task"
      },
      "For each account tagged REQUESTED": {
       "ItemsPath": "$.ResourceTagMappingList",
       "Iterator": {
        "StartAt": "Describe account",
        "States": {
         "Close account": {
          "Catch": [
           {
            "Comment": "Account closure limit reached",
            "ErrorEquals": [
             "Organizations.ConstraintViolationException"
            ],
            "Next": "Nothing to do"
           }
          ],
          "Next": "Tag with ACKNOWLEDGED",
          "Parameters": {
           "AccountId.$": "$.Account.Id"
          },
          "Resource": "arn:aws:states:::aws-sdk:organizations:closeAccount",
          "Retry": [
           {
            "BackoffRate": 1,
            "Comment": "Retry on throttle",
            "ErrorEquals": [
             "Organizations.TooManyRequestsException"
            ],
            "IntervalSeconds": 20,
            "MaxAttempts": 2
           }
          ],
          "Type": "Task"
         },
         "Describe account": {
          "Catch": [
           {
            "Comment": "Potential eventual consistency issue",
            "ErrorEquals": [
             "Organizations.AccountNotFoundException"
            ],
            "Next": "Nothing to do"
           }
          ],
          "Next": "Is account ACTIVE?",
          "Parameters": {
           "AccountId.$": "States.ArrayGetItem(States.StringSplit($.ResourceARN, '/'), 2)"
          },
          "Resource": "arn:aws:states:::aws-sdk:organizations:describeAccount",
          "Type": "Task"
         },
         "Is account ACTIVE?": {
          "Choices": [
           {
            "Next": "Close account",
            "StringEquals": "ACTIVE",
            "Variable": "$.Account.Status"
           }
          ],
          "Default": "Tag with ACKNOWLEDGED",
          "Type": "Choice"
         },
         "Nothing to do": {
          "Type": "Succeed"
         },
         "Tag with ACKNOWLEDGED": {
          "End": true,
          "Parameters": {
           "ResourceId.$": "$.Account.Id",
           "Tags": [
            {
             "Key": "organizations:account-closure",
             "Value": "ACKNOWLEDGED"
            }
           ]
          },
          "Resource": "arn:aws:states:::aws-sdk:organizations:tagResource",
          "Type": "Task"
         }
        }
       },
       "MaxConcurrency": 1,
       "Next": "Additional pages?",
       "ResultPath": "$._MapResult",
       "Type": "Map"
      },
      "Set empty pagination token": {
       "Next": "Find accounts tagged for closure",
       "Result": {
        "PaginationToken": ""
       },
       "Type": "Pass"
      }
     },
     "TimeoutSeconds": 300
    },
    "LoggingConfiguration": {
     "Destinations": [
      {
       "CloudWatchLogsLogGroup": {
        "LogGroupArn": {
         "Fn::GetAtt": [
          "LogGroup",
          "Arn"
         ]
        }
       }
      }
     ],
     "IncludeExecutionData": true,
     "Level": "ALL"
    },
    "RoleArn": {
     "Fn::GetAtt": [
      "StateMachineRole",
      "Arn"
     ]
    },
    "StateMachineType": "EXPRESS"
   },
   "Type": "AWS::StepFunctions::StateMachine"
  },
  "Rule": {
   "Properties": {
    "ScheduleExpression": "rate(1 hour)",
    "Targets": [
     {
      "Arn": {
       "Ref": "OrganizationsAccountClosureStateMachine"
      },
      "Id": "default",
      "RoleArn": {
       "Fn::GetAtt": [
        "RuleRole",
        "Arn"
       ]
      }
     }
    ]
   },
   "Type": "AWS::Events::Rule"
  },
  "RuleRole": {
   "Properties": {
    "AssumeRolePolicyDocument": {
     "Statement": [
      {
       "Action": [
        "sts:AssumeRole"
       ],
       "Effect": "Allow",
       "Principal": {
        "Service": "events.amazonaws.com"
       }
      }
     ],
     "Version": "2012-10-17"
    },
    "Policies": [
     {
      "PolicyDocument": {
       "Statement": [
        {
         "Action": [
          "states:StartExecution"
         ],
         "Effect": "Allow",
         "Resource": [
          {
           "Fn::GetAtt": [
            "OrganizationsAccountClosureStateMachine",
            "Arn"
           ]
          }
         ]
        }
       ],
       "Version": "2012-10-17"
      },
      "PolicyName": "StateMachineInvoke"
     }
    ]
   },
   "Type": "AWS::IAM::Role"
  },
  "StateMachineRole": {
   "Properties": {
    "AssumeRolePolicyDocument": {
     "Statement": [
      {
       "Action": [
        "sts:AssumeRole"
       ],
       "Effect": "Allow",
       "Principal": {
        "Service": "states.amazonaws.com"
       }
      }
     ],
     "Version": "2012-10-17"
    },
    "Policies": [
     {
      "PolicyDocument": {
       "Statement": [
        {
         "Action": [
          "organizations:TagResource"
         ],
         "Condition": {
          "ForAllValues:StringEquals": {
           "aws:TagKeys": [
            "organizations:account-closure"
           ]
          },
          "StringEquals": {
           "aws:RequestTag/organizations:account-closure": [
            "ACKNOWLEDGED"
           ],
           "aws:ResourceTag/organizations:account-closure": [
            "REQUESTED"
           ]
          }
         },
         "Effect": "Allow",
         "Resource": [
          {
           "Fn::Join": [
            ":",
            [
             "arn",
             {
              "Ref": "AWS::Partition"
             },
             "organizations",
             "",
             {
              "Ref": "AWS::AccountId"
             },
             {
              "Fn::Join": [
               "/",
               [
                "account",
                "*"
               ]
              ]
             }
            ]
           ]
          }
         ]
        },
        {
         "Action": [
          "organizations:CloseAccount",
          "organizations:DescribeAccount"
         ],
         "Condition": {
          "StringEquals": {
           "aws:ResourceTag/organizations:account-closure": [
            "REQUESTED"
           ]
          }
         },
         "Effect": "Allow",
         "Resource": [
          {
           "Fn::Join": [
            ":",
            [
             "arn",
             {
              "Ref": "AWS::Partition"
             },
             "organizations",
             "",
             {
              "Ref": "AWS::AccountId"
             },
             {
              "Fn::Join": [
               "/",
               [
                "account",
                "*"
               ]
              ]
             }
            ]
           ]
          }
         ]
        },
        {
         "Action": [
          "tag:GetResources"
         ],
         "Effect": "Allow",
         "Resource": [
          "*"
         ]
        },
        {
         "Action": [
          "logs:CreateLogDelivery",
          "logs:DeleteLogDelivery",
          "logs:DescribeLogGroups",
          "logs:DescribeResourcePolicies",
          "logs:GetLogDelivery",
          "logs:ListLogDeliveries",
          "logs:PutLogEvents",
          "logs:PutResourcePolicy",
          "logs:UpdateLogDelivery"
         ],
         "Effect": "Allow",
         "Resource": [
          "*"
         ]
        }
       ],
       "Version": "2012-10-17"
      },
      "PolicyName": "OrganizationsAccountClosure"
     }
    ]
   },
   "Type": "AWS::IAM::Role"
  }
 }
}

AWSTemplateFormatVersion: "2010-09-09"
Transform: AWS::Serverless-2016-10-31

Description: >
  Infrastructure as code for authorization layer (Amazon Verified Permissions and Cedar policies).

Resources:

  PolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    Properties:
      Description: Final version of the Cedar policy store that will be recreated independently.
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "actions": {
                "View": {
                  "appliesTo": {
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "required": true,
                          "type": "String"
                        }
                      }
                    },
                    "principalTypes": [
                      "User"
                    ]
                  },
                  "memberOf": []
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "required": true,
                          "type": "String"
                        }
                      }
                    },
                    "resourceTypes": [
                      "Book"
                    ]
                  },
                  "memberOf": []
                }
              },
              "entityTypes": {
                "Role": {
                  "memberOfTypes": [],
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": [
                    "Role"
                  ],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "memberOfTypes": [],
                  "shape": {
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "required": true,
                        "name": "User"
                      }
                    },
                    "type": "Record"
                  }
                }
              }
            }
          }

  PolicyStoreIdSSM:
    Type: AWS::SSM::Parameter
    Properties:
      Type: String
      Name: /bookstore-demo-app-with-authz/authorization/policy-store-id
      Value: !Ref PolicyStore

  RbacAdminStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows admins to list all books"
          Statement: |
            permit (
              principal in Bookstore::Role::"Admin",
              action in [ Bookstore::Action::"View" ],
              resource
            );

  RbacAdminForbidStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies admin Frank to list all books"
          Statement: |
            forbid (
              principal == Bookstore::User::"Frank",
              action in [ Bookstore::Action::"View" ],
              resource
            );

  RbacResourceOwnerStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows publishers to list books they have published"
          Statement: |
            permit (
              principal in Bookstore::Role::"Publisher",
              action in [ Bookstore::Action::"View" ],
              resource
            )
            when {
              principal == resource.owner
            };

  RbacExplicitStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows specific Publisher to list a specific book"
          Statement: |
            permit (
              principal == Bookstore::User::"Dante",
              action in [ Bookstore::Action::"View" ],
              resource == Bookstore::Book::"em1oadaa-b22k-4ea8-kk33-f6m217604o3m"
            );

  PermitAbacStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Allows customers with specific value for yearsAsMember attribute to list premium offers"
          Statement: |
            permit (
              principal in Bookstore::Role::"Customer",
              action in [ Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { principal has yearsAsMember && principal.yearsAsMember >= 2 };

  DenyAbacStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies customers with specific value for yearsAsMember attribute to list premium offers"
          Statement: |
            forbid (
              principal in Bookstore::Role::"Customer",
              action in [ Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { principal has yearsAsMember && principal.yearsAsMember < 2 };

  ContextStaticPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref PolicyStore
      Definition:
        Static:
          Description: "Denies access for users outside the US region"
          Statement: |
            forbid (
              principal,
              action in [ Bookstore::Action::"View", Bookstore::Action::"ViewWithPremiumOffers" ],
              resource
            )
            when { context.region != "US" };

Outputs:

  PolicyStoreId:
    Description: "Identifier of the Amazon Verified Permissions policy store."
    Value: !Ref PolicyStore

