{
    "AWSTemplateFormatVersion": "2010-09-09",
    "Description": "Step 2 of 3: Create the VPC infrastructure for the Puppet Quick Start.",
    "Parameters": {
        "SubnetCIDR": {
            "Description": "CIDR block for the public subnet",
            "Type": "String",
            "Default": "10.0.0.0/19",
            "AllowedPattern": "[a-zA-Z0-9]+\\..+"
        },
        "VPCCIDR": {
            "Description": "CIDR block for the VPC",
            "Type": "String",
            "Default": "10.0.0.0/16",
            "AllowedPattern": "[a-zA-Z0-9]+\\..+"
        },
        "PuppetMasterIP": {
            "Description": "IP for the Puppet master",
            "Type": "String",
            "Default": "10.0.0.10"
        },
        "PuppetAgentLinuxIP": {
            "Description": "IP for the Puppet agent",
            "Type": "String",
            "Default": "10.0.0.11"
        },
        "PuppetAgentWindowsIP": {
            "Description": "IP for the Puppet agent",
            "Type": "String",
            "Default": "10.0.0.12"
        }
    },
    "Resources": {
        "VPC": {
            "Type": "AWS::EC2::VPC",
            "Properties": {
                "CidrBlock": {
                    "Ref": "VPCCIDR"
                },
                "EnableDnsHostnames": true,
                "Tags": [
                    {
                        "Key": "Application",
                        "Value": {
                            "Ref": "AWS::StackName"
                        }
                    },
                    {
                        "Key": "Network",
                        "Value": "Public"
                    }
                ]
            }
        },
        "PublicSubnet": {
            "Type": "AWS::EC2::Subnet",
            "Properties": {
                "VpcId": {
                    "Ref": "VPC"
                },
                "CidrBlock": {
                    "Ref": "SubnetCIDR"
                },
                "MapPublicIpOnLaunch": true,
                "AvailabilityZone": {
                    "Fn::Select": [
                        1,
                        {
                            "Fn::GetAZs": ""
                        }
                    ]
                },
                "Tags": [
                    {
                        "Key": "Application",
                        "Value": {
                            "Ref": "AWS::StackName"
                        }
                    },
                    {
                        "Key": "Network",
                        "Value": "Public"
                    },
                    {
                        "Key": "Role",
                        "Value": "Public Subnet"
                    }
                ]
            }
        },
        "InternetGateway": {
            "Type": "AWS::EC2::InternetGateway",
            "Properties": {
                "Tags": [
                    {
                        "Key": "Application",
                        "Value": {
                            "Ref": "AWS::StackName"
                        }
                    },
                    {
                        "Key": "Network",
                        "Value": "Public"
                    }
                ]
            }
        },
        "AttachGateway": {
            "Type": "AWS::EC2::VPCGatewayAttachment",
            "Properties": {
                "VpcId": {
                    "Ref": "VPC"
                },
                "InternetGatewayId": {
                    "Ref": "InternetGateway"
                }
            }
        },
        "PublicRouteTable": {
            "Type": "AWS::EC2::RouteTable",
            "Properties": {
                "VpcId": {
                    "Ref": "VPC"
                },
                "Tags": [
                    {
                        "Key": "Application",
                        "Value": {
                            "Ref": "AWS::StackName"
                        }
                    },
                    {
                        "Key": "Network",
                        "Value": "Public Subnet"
                    }
                ]
            }
        },
        "PublicRoute": {
            "Type": "AWS::EC2::Route",
            "Properties": {
                "RouteTableId": {
                    "Ref": "PublicRouteTable"
                },
                "DestinationCidrBlock": "0.0.0.0/0",
                "GatewayId": {
                    "Ref": "InternetGateway"
                }
            }
        },
        "PublicSubnetRouteTableAssociation": {
            "Type": "AWS::EC2::SubnetRouteTableAssociation",
            "Properties": {
                "SubnetId": {
                    "Ref": "PublicSubnet"
                },
                "RouteTableId": {
                    "Ref": "PublicRouteTable"
                }
            }
        },
        "HostedZone": {
            "Type": "AWS::Route53::HostedZone",
            "Properties": {
                "HostedZoneConfig": {
                    "Comment": "Hosted zone for example.com"
                },
                "Name": "example.com",
                "VPCs": [
                    {
                        "VPCId": {
                            "Ref": "VPC"
                        },
                        "VPCRegion": {
                            "Ref": "AWS::Region"
                        }
                    }
                ]
            }
        },
        "PuppetMasterDNSRecord": {
            "Type": "AWS::Route53::RecordSet",
            "Properties": {
                "HostedZoneId": {
                    "Fn::Join": [
                        "",
                        [
                            "/hostedzone/",
                            {
                                "Ref": "HostedZone"
                            }
                        ]
                    ]
                },
                "Name": "puppet.example.com",
                "Type": "A",
                "TTL": "900",
                "ResourceRecords": [
                    {
                        "Ref": "PuppetMasterIP"
                    }
                ]
            }
        },
        "PuppetAgentLinuxDNSRecord": {
            "Type": "AWS::Route53::RecordSet",
            "Properties": {
                "HostedZoneId": {
                    "Fn::Join": [
                        "",
                        [
                            "/hostedzone/",
                            {
                                "Ref": "HostedZone"
                            }
                        ]
                    ]
                },
                "Name": "linuxagent.example.com",
                "Type": "A",
                "TTL": "900",
                "ResourceRecords": [
                    {
                        "Ref": "PuppetAgentLinuxIP"
                    }
                ]
            }
        },
        "PuppetAgentWindowsDNSRecord": {
            "Type": "AWS::Route53::RecordSet",
            "Properties": {
                "HostedZoneId": {
                    "Fn::Join": [
                        "",
                        [
                            "/hostedzone/",
                            {
                                "Ref": "HostedZone"
                            }
                        ]
                    ]
                },
                "Name": "windowsagent.example.com",
                "Type": "A",
                "TTL": "900",
                "ResourceRecords": [
                    {
                        "Ref": "PuppetAgentWindowsIP"
                    }
                ]
            }
        }
    },
    "Outputs": {
        "VPC": {
            "Value": {
                "Ref": "VPC"
            },
            "Description": "VPC ID"
        },
        "SubnetId": {
            "Value": {
                "Ref": "PublicSubnet"
            },
            "Description": "Subnet ID for the public subnet"
        }
    }
}

{
    "AWSTemplateFormatVersion": "2010-09-09",
    "Description": "Creates ImageBuilder component, Image Recipe, Infrastructure configuration, Distribution configuration, Image Pipeline, Lifecycle policy and a custom Workflow",
    "Resources": {
        "MyCfnComponent": {
            "Type": "AWS::ImageBuilder::Component",
            "Properties": {
                "Data": "name: Chef Client Execution on Linux\ndescription: This is a sample component that demonstrates how to download and execute a Chef recipe against a Linux server. This sample will install Chef using the Chef Software Install script. For more information about the installation script, review the documentation at https://docs.chef.io/packages/#chef-software-install-script.\nschemaVersion: 1.0\nconstants:\n  - ChefInstallationScriptSource:\n      type: string\n      value: https://omnitruck.chef.io/install.sh\n  - RecipeSource:\n      type: string\n      value: 's3://<enter_s3_bucket_name_here>/<enter_s3_object_key_here>'\nphases:\n  - name: build\n    steps:\n      - name: InstallationScript\n        action: ExecuteBash\n        inputs:\n          commands:\n            - echo \"$HOME/chef_install.sh\"\n      - name: DownloadInstallationScript\n        action: WebDownload\n        inputs:\n          - source: '{{ ChefInstallationScriptSource }}'\n            destination: '{{ build.InstallationScript.outputs.stdout }}'\n      - name: SetInstallationScriptExecutable\n        action: SetFilePermissions\n        inputs:\n          - path: '{{ build.InstallationScript.outputs.stdout }}'\n            permissions: 0700\n      - name: InstallChefClient\n        action: ExecuteBash\n        inputs:\n          commands:\n            - sudo '{{ build.InstallationScript.outputs.stdout }}' -c stable\n      - name: RecipeDestination\n        action: ExecuteBash\n        inputs:\n          commands:\n            - echo \"$HOME/recipe.rb\"\n      - name: DownloadRecipe\n        action: S3Download\n        inputs:\n          - source: '{{ RecipeSource }}'\n            destination: '{{ build.RecipeDestination.outputs.stdout }}'\n      - name: ApplyRecipe\n        action: ExecuteBinary\n        inputs:\n          path: chef-client\n          arguments:\n            - '--local-mode'\n            - '{{ build.RecipeDestination.outputs.stdout }}'\n            - '--chef-license'\n            - 'accept-no-persist'\n      - name: Cleanup\n        action: DeleteFile\n        inputs:\n          - path: '{{ build.RecipeDestination.outputs.stdout }}'\n          - path: '{{ build.InstallationScript.outputs.stdout }}'",
                "Name": "sample-component",
                "Platform": "Linux",
                "Version": "1.0.0"
            }
        },
        "MyCfnImageRecipe": {
            "Type": "AWS::ImageBuilder::ImageRecipe",
            "Properties": {
                "BlockDeviceMappings": [
                    {
                        "DeviceName": "/dev/xvda",
                        "Ebs": {
                            "DeleteOnTermination": true,
                            "Encrypted": false,
                            "VolumeSize": 30,
                            "VolumeType": "gp2"
                        }
                    }
                ],
                "Components": [
                    {
                        "ComponentArn": {
                            "Fn::Join": [
                                "",
                                [
                                    "arn:aws:imagebuilder:",
                                    {
                                        "Ref": "AWS::Region"
                                    },
                                    ":",
                                    {
                                        "Ref": "AWS::AccountId"
                                    },
                                    ":component/",
                                    {
                                        "Fn::GetAtt": [
                                            "MyCfnComponent",
                                            "Name"
                                        ]
                                    },
                                    "/x.x.x"
                                ]
                            ]
                        }
                    },
                    {
                        "ComponentArn": {
                            "Fn::Join": [
                                "",
                                [
                                    "arn:aws:imagebuilder:",
                                    {
                                        "Ref": "AWS::Region"
                                    },
                                    ":aws:component/chrony-time-configuration-test/x.x.x"
                                ]
                            ]
                        }
                    }
                ],
                "Name": "sample-recipe",
                "ParentImage": {
                    "Fn::Join": [
                        "",
                        [
                            "arn:aws:imagebuilder:",
                            {
                                "Ref": "AWS::Region"
                            },
                            ":aws:image/amazon-linux-2-ecs-optimized-x86/x.x.x"
                        ]
                    ]
                },
                "Version": "1.0.0",
                "WorkingDirectory": "/tmp"
            }
        },
        "IAMRoleImageBuilderA8786988": {
            "Type": "AWS::IAM::Role",
            "Properties": {
                "AssumeRolePolicyDocument": {
                    "Statement": [
                        {
                            "Action": "sts:AssumeRole",
                            "Effect": "Allow",
                            "Principal": {
                                "Service": "ec2.amazonaws.com"
                            }
                        }
                    ],
                    "Version": "2012-10-17"
                },
                "ManagedPolicyArns": [
                    {
                        "Fn::Join": [
                            "",
                            [
                                "arn:",
                                {
                                    "Ref": "AWS::Partition"
                                },
                                ":iam::aws:policy/AdministratorAccess"
                            ]
                        ]
                    }
                ]
