{
    "AWSTemplateFormatVersion": "2010-09-09",
    "Description": "Sample Beanstalk environmment template",
    "Conditions": {
        "CreateNewBeanstalkApp": {
            "Fn::Equals": [
                {
                    "Ref": "ExistingBeanstalkApplicationName"
                },
                ""
            ]
        },
        "CreateNewBeanstalkEnv": {
            "Fn::Equals": [
                {
                    "Ref": "ExistingBlueEnvironmentName"
                },
                ""
            ]
        },
        "CreateSampleAppForBeanstalk": {
            "Fn::Equals": [
                {
                    "Ref": "AppPackageS3Bucket"
                },
                "elasticbeanstalk-samples"
            ]
        }
    },
    "Parameters": {
        "AppPackageS3Bucket": {
            "Default": "elasticbeanstalk-samples",
            "Description": "Provide the S3 bucket where the Application Package exists for creating a new Beanstalk environment. This parameter can be ignored if using an existing Environment.",
            "Type": "String"
        },
        "AppPackageS3key": {
            "Default": "php-sample.zip",
            "Description": "Provide the S3 bucket key with the zip file package name for creating a new Beanstalk environment. This parameter can be ignored if using an existing Environment",
            "Type": "String"
        },
        "ExistingBeanstalkApplicationName": {
            "Default": "",
            "Description": "OPTIONAL: Required if the parameter 'ExistingBlueEnvironmentName' is provided. Give the Name of the Existing Beantalk Application where the existing Beanstalk Environment is running. Leave in blank if you want to create a new Application",
            "Type": "String"
        },
        "ExistingBlueEnvironmentName": {
            "Default": "",
            "Description": "Name of the Existing Beanstalk Environment as Blue Environment. Leave it blank if you want to create a new Environment. Provide a value to this parameter for which you would like to utilize the cost efficient Blue-Green deployments by creating a temporary cloned environment for routing the live traffic when this environment is in the Deployment/Test lifecycle",
            "Type": "String"
        },
        "GreenEnvironmentName": {
            "Default": "GreenEnvironment",
            "Description": "Provide a Name for the Green Environment, which will be the clone of the Blue Environment where the traffic will be routed temporarily for the amount of time the Blue Environment is completed with the deployment and tested. After the successful deployment to Blue Environment, the traffic will be routed back to Blue and the Green Environment will be terminated",
            "Type": "String"
        },
        "NewBeanstalkApplicationName": {
            "Default": "BlueGreenBeanstalkApplication",
            "Description": "OPTIONAL:Provide a name for a new Beantalk Application where the new Blue Environment and the clone will be created. If not provided, the name will be 'BlueGreenBeanstalkApplication' by default. Value for this parameter is required only when you leave the 'ExistingBlueEnvironmentName' and 'ExistingBeanstalkApplicationName' property empty",
            "Type": "String"
        },
        "NewBlueEnvironmentName": {
            "Default": "BlueEnvironment",
            "Description": "Provide a name for creating a new Beanstalk Environment as Blue Environment that uses a Sample Application. This is the main environment from which a temporary clone called 'Green Environment' will be created to route the live traffic until the deployment is completed and tested with this one. Value for this parameter is required only when you leave the 'ExistingBlueEnvironmentName' property empty",
            "Type": "String"
        },
        "SolutionStackForNewBeanstalkEnv": {
            "Default": "64bit Amazon Linux 2023 v4.13.6 running PHP 8.3",
            "Description": "Provide a name for the Beanstalk Solution stack for launching the new Blue Environment. If not provided, the default will be a PHP solution stack. Please refer the following document https://docs.aws.amazon.com/elasticbeanstalk/latest/dg/concepts.platforms.html for all the solution stack values. Value for this parameter is required only when you leave the 'ExistingBlueEnvironmentName' property empty",
            "Type": "String"
        }
    },
    "Resources": {
        "BeanstalkVpc": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "CidrBlock": "10.98.0.0/16",
                "EnableDnsSupport": true,
                "EnableDnsHostnames": true
            },
            "Type": "AWS::EC2::VPC"
        },
        "BeanstalkInternetGateway": {
            "Condition": "CreateNewBeanstalkEnv",
            "Type": "AWS::EC2::InternetGateway"
        },
        "BeanstalkVpcGatewayAttachment": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "VpcId": { "Ref": "BeanstalkVpc" },
                "InternetGatewayId": { "Ref": "BeanstalkInternetGateway" }
            },
            "Type": "AWS::EC2::VPCGatewayAttachment"
        },
        "BeanstalkPublicSubnet1": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "VpcId": { "Ref": "BeanstalkVpc" },
                "CidrBlock": "10.98.0.0/24",
                "AvailabilityZone": { "Fn::Select": [0, { "Fn::GetAZs": "" }] },
                "MapPublicIpOnLaunch": true
            },
            "Type": "AWS::EC2::Subnet"
        },
        "BeanstalkPublicSubnet2": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "VpcId": { "Ref": "BeanstalkVpc" },
                "CidrBlock": "10.98.1.0/24",
                "AvailabilityZone": { "Fn::Select": [1, { "Fn::GetAZs": "" }] },
                "MapPublicIpOnLaunch": true
            },
            "Type": "AWS::EC2::Subnet"
        },
        "BeanstalkRouteTable": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "VpcId": { "Ref": "BeanstalkVpc" }
            },
            "Type": "AWS::EC2::RouteTable"
        },
        "BeanstalkDefaultRoute": {
            "Condition": "CreateNewBeanstalkEnv",
            "DependsOn": "BeanstalkVpcGatewayAttachment",
            "Properties": {
                "RouteTableId": { "Ref": "BeanstalkRouteTable" },
                "DestinationCidrBlock": "0.0.0.0/0",
                "GatewayId": { "Ref": "BeanstalkInternetGateway" }
            },
            "Type": "AWS::EC2::Route"
        },
        "BeanstalkSubnet1RouteTableAssociation": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "SubnetId": { "Ref": "BeanstalkPublicSubnet1" },
                "RouteTableId": { "Ref": "BeanstalkRouteTable" }
            },
            "Type": "AWS::EC2::SubnetRouteTableAssociation"
        },
        "BeanstalkSubnet2RouteTableAssociation": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "SubnetId": { "Ref": "BeanstalkPublicSubnet2" },
                "RouteTableId": { "Ref": "BeanstalkRouteTable" }
            },
            "Type": "AWS::EC2::SubnetRouteTableAssociation"
        },
        "BeanstalkAppVersion": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "ApplicationName": {
                    "Fn::If": [
                        "CreateNewBeanstalkApp",
                        {
                            "Ref": "BeanstalkApplication"
                        },
                        {
                            "Ref": "ExistingBeanstalkApplicationName"
                        }
                    ]
                },
                "Description": "my sample version",
                "SourceBundle": {
                    "S3Bucket": {
                        "Fn::If": [
                            "CreateSampleAppForBeanstalk",
                            {
                                "Fn::Join": [
                                    "",
                                    [
                                        {
                                            "Ref": "AppPackageS3Bucket"
                                        },
                                        "-",
                                        {
                                            "Ref": "AWS::Region"
                                        }
                                    ]
                                ]
                            },
                            {
                                "Ref": "AppPackageS3Bucket"
                            }
                        ]
                    },
                    "S3Key": {
                        "Ref": "AppPackageS3key"
                    }
                }
            },
            "Type": "AWS::ElasticBeanstalk::ApplicationVersion"
        },
        "BeanstalkApplication": {
            "Condition": "CreateNewBeanstalkApp",
            "Properties": {
                "ApplicationName": {
                    "Ref": "NewBeanstalkApplicationName"
                },
                "Description": "AWS Elastic Beanstalk PHP Sample Application"
            },
            "Type": "AWS::ElasticBeanstalk::Application"
        },
        "BeanstalkEnvironment": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "ApplicationName": {
                    "Fn::If": [
                        "CreateNewBeanstalkApp",
                        {
                            "Ref": "BeanstalkApplication"
                        },
                        {
                            "Ref": "ExistingBeanstalkApplicationName"
                        }
                    ]
                },
                "Description": "AWS Elastic Beanstalk Environment running PHP Sample Application",
                "EnvironmentName": {
                    "Ref": "NewBlueEnvironmentName"
                },
                "OptionSettings": [
                    {
                        "Namespace": "aws:autoscaling:launchconfiguration",
                        "OptionName": "IamInstanceProfile",
                        "Value": {
                            "Ref": "BeanstalkInstanceProfile"
                        }
                    },
                    {
                        "Namespace": "aws:elasticbeanstalk:environment",
                        "OptionName": "ServiceRole",
                        "Value": {
                            "Ref": "BeanstalkServiceRole"
                        }
                    },
                    {
                        "Namespace": "aws:ec2:vpc",
                        "OptionName": "VPCId",
                        "Value": { "Ref": "BeanstalkVpc" }
                    },
                    {
                        "Namespace": "aws:ec2:vpc",
                        "OptionName": "Subnets",
                        "Value": { "Fn::Join": [",", [{ "Ref": "BeanstalkPublicSubnet1" }, { "Ref": "BeanstalkPublicSubnet2" }]] }
                    },
                    {
                        "Namespace": "aws:ec2:vpc",
                        "OptionName": "ELBSubnets",
                        "Value": { "Fn::Join": [",", [{ "Ref": "BeanstalkPublicSubnet1" }, { "Ref": "BeanstalkPublicSubnet2" }]] }
                    },
                    {
                        "Namespace": "aws:ec2:vpc",
                        "OptionName": "AssociatePublicIpAddress",
                        "Value": "true"
                    }
                ],
                "SolutionStackName": {
                    "Ref": "SolutionStackForNewBeanstalkEnv"
                },
                "VersionLabel": {
                    "Ref": "BeanstalkAppVersion"
                }
            },
            "Type": "AWS::ElasticBeanstalk::Environment"
        },
        "BeanstalkInstanceProfile": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "Path": "/",
                "Roles": [
                    {
                        "Ref": "BeanstalkInstanceProfileRole"
                    }
                ]
            },
            "Type": "AWS::IAM::InstanceProfile"
        },
        "BeanstalkInstanceProfileRole": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "AssumeRolePolicyDocument": {
                    "Statement": [
                        {
                            "Action": [
                                "sts:AssumeRole"
                            ],
                            "Effect": "Allow",
                            "Principal": {
                                "Service": [
                                    "ec2.amazonaws.com"
                                ]
                            }
                        }
                    ],
                    "Version": "2012-10-17"
                },
                "Path": "/",
                "Policies": [
                    {
                        "PolicyDocument": {
                            "Statement": [
                                {
                                    "Action": [
                                        "s3:Get*",
                                        "s3:List*",
                                        "s3:PutObject"
                                    ],
                                    "Effect": "Allow",
                                    "Resource": [
                                        {
                                            "Fn::Join": [
                                                "",
                                                [
                                                    "arn:",
                                                    {
                                                        "Ref": "AWS::Partition"
                                                    },
                                                    ":s3:::elasticbeanstalk-*-",
                                                    {
                                                        "Ref": "AWS::AccountId"
                                                    }
                                                ]
                                            ]
                                        },
                                        {
                                            "Fn::Join": [
                                                "",
                                                [
                                                    "arn:",
                                                    {
                                                        "Ref": "AWS::Partition"
                                                    },
                                                    ":s3:::elasticbeanstalk-*-",
                                                    {
                                                        "Ref": "AWS::AccountId"
                                                    },
                                                    "/*"
                                                ]
                                            ]
                                        },
                                        {
                                            "Fn::Join": [
                                                "",
                                                [
                                                    "arn:",
                                                    {
                                                        "Ref": "AWS::Partition"
                                                    },
                                                    ":s3:::elasticbeanstalk-*-",
                                                    {
                                                        "Ref": "AWS::AccountId"
                                                    },
                                                    "-*"
                                                ]
                                            ]
                                        },
                                        {
                                            "Fn::Join": [
                                                "",
                                                [
                                                    "arn:",
                                                    {
                                                        "Ref": "AWS::Partition"
                                                    },
                                                    ":s3:::elasticbeanstalk-*-",
                                                    {
                                                        "Ref": "AWS::AccountId"
                                                    },
                                                    "-*/*"
                                                ]
                                            ]
                                        }
                                    ],
                                    "Sid": "BucketAccess"
                                },
                                {
                                    "Action": [
                                        "cloudwatch:PutMetricData"
                                    ],
                                    "Effect": "Allow",
                                    "Resource": "*",
                                    "Sid": "MetricsAccess"
                                },
                                {
                                    "Action": [
                                        "logs:PutLogEvents",
                                        "logs:CreateLogStream",
                                        "logs:DescribeLogStreams",
                                        "logs:DescribeLogGroups"
                                    ],
                                    "Effect": "Allow",
                                    "Resource": [
                                        "arn:aws:logs:*:*:log-group:/aws/elasticbeanstalk*"
                                    ],
                                    "Sid": "CloudWatchLogsAccess"
                                }
                            ],
                            "Version": "2012-10-17"
                        },
                        "PolicyName": "root"
                    }
                ]
            },
            "Type": "AWS::IAM::Role"
        },
        "BeanstalkServiceRole": {
            "Condition": "CreateNewBeanstalkEnv",
            "Properties": {
                "AssumeRolePolicyDocument": {
                    "Statement": [
                        {
                            "Action": "sts:AssumeRole",
                            "Condition": {
                                "StringEquals": {
                                    "sts:ExternalId": "elasticbeanstalk"
                                }
                            },
                            "Effect": "Allow",
                            "Principal": {
                                "Service": "elasticbeanstalk.amazonaws.com"
                            },
                            "Sid": ""
                        }
                    ],
                    "Version": "2012-10-17"
                },
                "Path": "/",
                "Policies": [
                    {
                        "PolicyDocument": {
                            "Statement": [
                                {
                                    "Action": [
                                        "elasticloadbalancing:DescribeInstanceHealth",
                                        "ec2:DescribeInstances",
                                        "ec2:DescribeInstanceStatus",
                                        "ec2:GetConsoleOutput",
                                        "ec2:AssociateAddress",
                                        "ec2:DescribeAddresses",
                                        "ec2:DescribeSecurityGroups",
                                        "sqs:GetQueueAttributes",
                                        "sqs:GetQueueUrl",
                                        "autoscaling:DescribeAutoScalingGroups",
                                        "autoscaling:DescribeAutoScalingInstances",
                                        "autoscaling:DescribeScalingActivities",
                                        "autoscaling:DescribeNotificationConfigurations"
                                    ],
                                    "Effect": "Allow",
                                    "Resource": [
                                        "*"
                                    ]
                                }
                            ],
                            "Version": "2012-10-17"
                        },
                        "PolicyName": "root"
                    }
                ]
            },
            "Type": "AWS::IAM::Role"
        }
    },
    "Outputs": {
        "BeanstalkEnvironment": {
            "Value": {
                "Fn::If": [
                    "CreateNewBeanstalkEnv",
                    {
                        "Ref": "BeanstalkEnvironment"
                    },
                    ""
                ]
            }
        },
        "BeanstalkEnvEndPointUrl": {
            "Description": "New Beanstalk Environment Endpoint URL",
            "Value": {
                "Fn::If": [
                    "CreateNewBeanstalkEnv",
                    {
                        "Fn::GetAtt": [
                            "BeanstalkEnvironment",
                            "EndpointURL"
                        ]
                    },
                    ""
                ]
            }
        }
    }
}

AWSTemplateFormatVersion: 2010-09-09
Description: An AppSync API with JavaScript resolvers with a DynamoDB data source
Resources:
  ApiF70053CD:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      AuthenticationType: API_KEY
      Name: TodoAPIwithJs
  ApiSchema510EECD7:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId:
        Fn::GetAtt:
          - ApiF70053CD
          - ApiId
      Definition: |
        input CreateTodoInput {
          title: String
          description: String
          owner: String
        }

        input DeleteTodoInput {
          id: ID!
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(input: DeleteTodoInput!): Todo
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(filter: TableTodoFilterInput, limit: Int, nextToken: String): TodoConnection
          queryTodosByOwnerIndex(owner: String!, first: Int, after: String): TodoConnection
        }

        type Subscription {
          onCreateTodo(id: ID, title: String, description: String, owner: String): Todo @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo(id: ID, title: String, description: String, owner: String): Todo @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo(id: ID, title: String, description: String, owner: String): Todo @aws_subscribe(mutations: ["deleteTodo"])
        }

        input TableBooleanFilterInput {
          ne: Boolean
          eq: Boolean
        }

        input TableFloatFilterInput {
          ne: Float
          eq: Float
          le: Float
          lt: Float
          ge: Float
          gt: Float
          contains: Float
          notContains: Float
          between: [Float]
        }

        input TableIDFilterInput {
          ne: ID
          eq: ID
          le: ID
          lt: ID
          ge: ID
          gt: ID
          contains: ID
          notContains: ID
          between: [ID]
          beginsWith: ID
        }

        input TableIntFilterInput {
          ne: Int
          eq: Int
          le: Int
          lt: Int
          ge: Int
          gt: Int
          contains: Int
          notContains: Int
          between: [Int]
        }

        input TableStringFilterInput {
          ne: String
          eq: String
          le: String
          lt: String
          ge: String
          gt: String
          contains: String
          notContains: String
          between: [String]
          beginsWith: String
        }

        input TableTodoFilterInput {
          id: TableIDFilterInput
          title: TableStringFilterInput
          description: TableStringFilterInput
          owner: TableStringFilterInput
        }

        type Todo {
          id: ID!
          title: String
          description: String
          owner: String
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          owner: String
        }
  ApiDefaultApiKeyF991C37B:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId:
        Fn::GetAtt:
          - ApiF70053CD
          - ApiId
    DependsOn:
      - ApiSchema510EECD7
  ApitableServiceRole0D5FB338:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Statement:
          - Action: sts:AssumeRole
            Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
        Version: '2012-10-17'
  ApitableServiceRoleDefaultPolicy3E188D7B:
    Type: AWS::IAM::Policy
    Properties:
      PolicyDocument:
        Statement:
          - Action:
              - dynamodb:BatchGetItem
              - dynamodb:BatchWriteItem
              - dynamodb:ConditionCheckItem
              - dynamodb:DeleteItem
              - dynamodb:DescribeTable
              - dynamodb:GetItem
              - dynamodb:GetRecords
              - dynamodb:GetShardIterator
              - dynamodb:PutItem
              - dynamodb:Query
              - dynamodb:Scan
              - dynamodb:UpdateItem
            Effect: Allow
            Resource:
              - Fn::GetAtt:
                  - TodoTable585F1D6B
                  - Arn
              - Fn::Join:
                  - ''
                  - - Fn::GetAtt:
                        - TodoTable585F1D6B
                        - Arn
                    - /index/*
        Version: '2012-10-17'
      PolicyName: ApitableServiceRoleDefaultPolicy3E188D7B
      Roles:
        - Ref: ApitableServiceRole0D5FB338
  Apitable9F4D58B6:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId:
        Fn::GetAtt:
          - ApiF70053CD
          - ApiId
      Name: table
      Type: AMAZON_DYNAMODB
      DynamoDBConfig:
        AwsRegion:
          Ref: AWS::Region
        TableName:
          Ref: TodoTable585F1D6B
      ServiceRoleArn:
        Fn::GetAtt:
          - ApitableServiceRole0D5FB338
          - Arn
  ApitableCREATEITEMFunction64BB3F3D:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId:
        Fn::GetAtt:
          - ApiF70053CD
          - ApiId
      DataSourceName: table
      Name: CREATE_ITEM
      Runtime:
        Name: 'APPSYNC_JS'
        RuntimeVersion: '1.0.0'
      Code: |
        /**
         * AppSync function: creates a new item in a DynamoDB table.
         * Find more samples and templates at https://github.com/aws-samples/aws-appsync-resolver-samples
         */

        import { util } from '@aws-appsync/utils';

        /**
        * Creates a new item in a DynamoDB table
        * @param ctx contextual information about the request
        */
        export function request(ctx) {
          const { input: values } = ctx.arguments;
          const key = { id: util.autoId() };
          const condition = { and: [{ id: { attributeExists: false } }] };
          console.log('--> create todo with requested values: ', values);
          return dynamodbPutRequest({ key, values, condition });
        }

        /**
        * Returns the result
        * @param ctx contextual information about the request
        */
        export function response(ctx) {
          const { error, result } = ctx;
