        ]
      }
    },
    "CIS310CloudWatchAlarm" : {
      "Type" : "AWS::CloudWatch::Alarm",
      "DependsOn" : [ "AlarmTopic" ],
      "Properties" : {
        "AlarmName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-310", "alarm" ] },
        "AlarmDescription" : "Alarm for security group changes (Scored)",
        "AlarmActions" : [ { "Ref" : "AlarmTopic" } ],
        "MetricName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-310", "metric" ] },
        "Namespace" : "CISBenchmark",
        "ComparisonOperator" : "GreaterThanOrEqualToThreshold",
        "EvaluationPeriods" : 1,
        "Period" : 300,
        "Statistic" : "Sum",
        "Threshold" : 1
      }
    },

    "CIS311MetricFilter" : {
      "Type" : "AWS::Logs::MetricFilter",
      "DependsOn" : [ "TrailLogGroup" ],
      "Properties" : {
        "FilterPattern" : "{($.eventName = CreateNetworkAcl) || ($.eventName = CreateNetworkAclEntry) || ($.eventName = DeleteNetworkAcl) || ($.eventName = DeleteNetworkAclEntry) || ($.eventName = ReplaceNetworkAclEntry) || ($.eventName = ReplaceNetworkAclAssociation)}",
        "LogGroupName" : { "Ref" : "TrailLogGroup" },
        "MetricTransformations" : [
          {
            "MetricValue" : 1,
            "MetricNamespace" : "CISBenchmark",
            "MetricName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-311", "metric" ] }
          }
        ]
      }
    },
    "CIS311CloudWatchAlarm" : {
      "Type" : "AWS::CloudWatch::Alarm",
      "DependsOn" : [ "AlarmTopic" ],
      "Properties" : {
        "AlarmName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-311", "alarm" ] },
        "AlarmDescription" : "Alarm for changes to Network Access Control Lists (Scored)",
        "AlarmActions" : [ { "Ref" : "AlarmTopic" } ],
        "MetricName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-311", "metric" ] },
        "Namespace" : "CISBenchmark",
        "ComparisonOperator" : "GreaterThanOrEqualToThreshold",
        "EvaluationPeriods" : 1,
        "Period" : 300,
        "Statistic" : "Sum",
        "Threshold" : 1
      }
    },

    "CIS312MetricFilter" : {
      "Type" : "AWS::Logs::MetricFilter",
      "DependsOn" : [ "TrailLogGroup" ],
      "Properties" : {
        "FilterPattern" : "{($.eventName = CreateCustomerGateway) || ($.eventName = DeleteCustomerGateway) || ($.eventName = AttachInternetGateway) || ($.eventName = CreateInternetGateway) || ($.eventName = DeleteInternetGateway) || ($.eventName = DetachInternetGateway)}",
        "LogGroupName" : { "Ref" : "TrailLogGroup" },
        "MetricTransformations" : [
          {
            "MetricValue" : 1,
            "MetricNamespace" : "CISBenchmark",
            "MetricName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-312", "metric" ] }
          }
        ]
      }
    },
    "CIS312CloudWatchAlarm" : {
      "Type" : "AWS::CloudWatch::Alarm",
      "DependsOn" : [ "AlarmTopic" ],
      "Properties" : {
        "AlarmName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-312", "alarm" ] },
        "AlarmDescription" : "Alarm for changes to network gateways (Scored)",
        "AlarmActions" : [ { "Ref" : "AlarmTopic" } ],
        "MetricName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-312", "metric" ] },
        "Namespace" : "CISBenchmark",
        "ComparisonOperator" : "GreaterThanOrEqualToThreshold",
        "EvaluationPeriods" : 1,
        "Period" : 300,
        "Statistic" : "Sum",
        "Threshold" : 1
      }
    },

    "CIS313MetricFilter" : {
      "Type" : "AWS::Logs::MetricFilter",
      "DependsOn" : [ "TrailLogGroup" ],
      "Properties" : {
        "FilterPattern" : "{($.eventName = CreateRoute) || ($.eventName = CreateRouteTable) || ($.eventName = ReplaceRoute) || ($.eventName = ReplaceRouteTableAssociation) || ($.eventName = DeleteRouteTable) || ($.eventName = DeleteRoute) || ($.eventName = DisassociateRouteTable)}",
        "LogGroupName" : { "Ref" : "TrailLogGroup" },
        "MetricTransformations" : [
          {
            "MetricValue" : 1,
            "MetricNamespace" : "CISBenchmark",
            "MetricName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-313", "metric" ] }
          }
        ]
      }
    },
    "CIS313CloudWatchAlarm" : {
      "Type" : "AWS::CloudWatch::Alarm",
      "DependsOn" : [ "AlarmTopic" ],
      "Properties" : {
        "AlarmName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-313", "alarm" ] },
        "AlarmDescription" : "Alarm for route table changes (Scored)",
        "AlarmActions" : [ { "Ref" : "AlarmTopic" } ],
        "MetricName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-313", "metric" ] },
        "Namespace" : "CISBenchmark",
        "ComparisonOperator" : "GreaterThanOrEqualToThreshold",
        "EvaluationPeriods" : 1,
        "Period" : 300,
        "Statistic" : "Sum",
        "Threshold" : 1
      }
    },

    "CIS314MetricFilter" : {
      "Type" : "AWS::Logs::MetricFilter",
      "DependsOn" : [ "TrailLogGroup" ],
      "Properties" : {
        "FilterPattern" : "{($.eventName = CreateVpc) || ($.eventName = DeleteVpc) || ($.eventName = ModifyVpcAttribute) || ($.eventName = AcceptVpcPeeringConnection) || ($.eventName = CreateVpcPeeringConnection) || ($.eventName = DeleteVpcPeeringConnection) || ($.eventName = RejectVpcPeeringConnection) || ($.eventName = AttachClassicLinkVpc) || ($.eventName = DetachClassicLinkVpc) || ($.eventName = DisableVpcClassicLink) || ($.eventName = EnableVpcClassicLink)}",
        "LogGroupName" : { "Ref" : "TrailLogGroup" },
        "MetricTransformations" : [
          {
            "MetricValue" : 1,
            "MetricNamespace" : "CISBenchmark",
            "MetricName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-314", "metric" ] }
          }
        ]
      }
    },
    "CIS314CloudWatchAlarm" : {
      "Type" : "AWS::CloudWatch::Alarm",
      "DependsOn" : [ "AlarmTopic" ],
      "Properties" : {
        "AlarmName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-314", "alarm" ] },
        "AlarmDescription" : "Alarm for VPC changes (Scored)",
        "AlarmActions" : [ { "Ref" : "AlarmTopic" } ],
        "MetricName" : { "Fn::FindInMap" : [ "FilterAlarmNames", "CIS-314", "metric" ] },
        "Namespace" : "CISBenchmark",
        "ComparisonOperator" : "GreaterThanOrEqualToThreshold",
        "EvaluationPeriods" : 1,
        "Period" : 300,
        "Statistic" : "Sum",
        "Threshold" : 1
      }
    }

  },

  "Outputs" : {

    "TrailBucket" : {
      "Description" : "S3 CloudTrail Bucket",
      "Value" : { "Ref" : "CloudTrailS3Bucket" }
    },
    "TrailName" : {
      "Description" : "CloudTrail Trail Name",
      "Value" : { "Ref" : "Trail" }
    }
  }
}

{
  "AWSTemplateFormatVersion":"2010-09-09",
  "Description":"Dromedary demo - iam roles & policies and instance-profiles",
  "Resources":{
    "InstanceRole":{
      "Type":"AWS::IAM::Role",
      "Properties":{
        "AssumeRolePolicyDocument":{
          "Statement":[
            {
              "Effect":"Allow",
              "Principal":{
                "Service":[
                  "ec2.amazonaws.com"
                ]
              },
              "Action":[
                "sts:AssumeRole"
              ]
            }
          ]
        },
        "Path":"/",
        "Policies":[
          {
            "PolicyName":"AllowAll",
            "PolicyDocument":{
              "Statement":[
                {
                  "Effect":"Allow",
                  "Action":"*",
                  "Resource":"*"
                }
              ]
            }
          }
        ]
      }
    },
    "InstanceProfile":{
      "Type":"AWS::IAM::InstanceProfile",
      "Properties":{
        "Path":"/",
        "Roles":[
          {
            "Ref":"InstanceRole"
          }
        ]
      }
    },
    "CodeDeployTrustRole":{
      "Type":"AWS::IAM::Role",
      "Properties":{
        "AssumeRolePolicyDocument":{
          "Statement":[
            {
              "Sid":"1",
              "Effect":"Allow",
              "Principal":{
                "Service":[
                  "codedeploy.us-east-1.amazonaws.com",
                  "codedeploy.us-west-2.amazonaws.com"
                ]
              },
              "Action":"sts:AssumeRole"
            }
          ]
        },
        "Path":"/",
        "Policies":[
          {
            "PolicyName":"CodeDeployPolicy",
            "PolicyDocument":{
              "Statement":[
                {
                  "Effect":"Allow",
                  "Action":[
                    "ec2:Describe*"
                  ],
                  "Resource":[
                    "*"
                  ]
                },
                {
                  "Effect":"Allow",
                  "Resource":[
                    "*"
                  ],
                  "Action":[
                    "autoscaling:CompleteLifecycleAction",
                    "autoscaling:DeleteLifecycleHook",
                    "autoscaling:DescribeLifecycleHooks",
                    "autoscaling:DescribeAutoScalingGroups",
                    "autoscaling:PutLifecycleHook",
                    "autoscaling:RecordLifecycleActionHeartbeat"
                  ]
                }
              ]
            }
          }
        ]
      }
    },
    "CodePipelineTrustRole":{
      "Type":"AWS::IAM::Role",
      "Properties":{
        "AssumeRolePolicyDocument":{
          "Statement":[
            {
              "Sid":"1",
              "Effect":"Allow",
              "Principal":{
                "Service":[
                  "codepipeline.amazonaws.com"
                ]
              },
              "Action":"sts:AssumeRole"
            }
          ]
        },
        "Path":"/",
        "Policies":[
          {
            "PolicyName":"CodePipelinePolicy",
            "PolicyDocument":{
              "Version":"2012-10-17",
              "Statement":[
                {
                  "Action":[
                    "s3:GetObject",
                    "s3:GetObjectVersion",
                    "s3:GetBucketVersioning"
                  ],
                  "Resource":"*",
                  "Effect":"Allow"
                },
                {
                  "Action":[
                    "s3:PutObject"
                  ],
                  "Resource":[
                    "arn:aws:s3:::codepipeline*",
                    "arn:aws:s3:::dromedary*",
                    "arn:aws:s3:::elasticbeanstalk*"
                  ],
                  "Effect":"Allow"
                },
                {
                  "Action":[
                    "codedeploy:CreateDeployment",
                    "codedeploy:GetApplicationRevision",
                    "codedeploy:GetDeployment",
                    "codedeploy:GetDeploymentConfig",
                    "codedeploy:RegisterApplicationRevision"
                  ],
                  "Resource":"*",
                  "Effect":"Allow"
                },
                {
                  "Action":[
                    "elasticbeanstalk:*",
                    "ec2:*",
                    "elasticloadbalancing:*",
                    "autoscaling:*",
                    "cloudwatch:*",
                    "s3:*",
                    "sns:*",
                    "cloudformation:*",
                    "rds:*",
                    "sqs:*",
                    "ecs:*",
                    "iam:PassRole"
                  ],
                  "Resource":"*",
                  "Effect":"Allow"
                },
                {
                  "Action":[
                    "lambda:InvokeFunction",
                    "lambda:ListFunctions"
                  ],
                  "Resource":"*",
                  "Effect":"Allow"
                }
              ]
            }
          }
        ]
      }
    }
  },
  "Outputs":{
    "StackName":{
      "Value":{
        "Ref":"AWS::StackName"
      }
    },
    "CodeDeployServiceRoleARN":{
      "Description":"The ARN of the Code Deploy Trust Role, which is needed to configure Code Deploy",
      "Value":{
        "Fn::GetAtt":[
          "CodeDeployTrustRole",
          "Arn"
        ]
      }
    },
    "CodePipelineTrustRoleARN":{
      "Description":"The ARN of the Code Pipeline Trust Role, which is needed to configure Code Pipeline",
      "Value":{
        "Fn::GetAtt":[
          "CodePipelineTrustRole",
          "Arn"
        ]
      }
    },
    "InstanceProfile":{
      "Description":"Name if instance-profile for Jenkins and application instances",
      "Value":{
        "Ref":"InstanceProfile"
      }
    },
    "InstanceRole":{
      "Description":"IAM Role for Jenkins and application instance profile",
      "Value":{
        "Ref":"InstanceRole"
      }
    }
  }
}

# etc/squarespace-commerce-webhooks.yml
AWSTemplateFormatVersion: "2010-09-09"
Description: >-
  Wires up Stripe payments webhooks and the Squarespace Commerce API to allow
  sales notifications to Slack

Parameters:
  SquarespaceApiToken: { Type: String }
  StripeWebhookSigningSecret: { Type: String }
  SlackMessageRelayTopicArn: { Type: String }

Resources:
  # API Gateway
  RestApi:
    Type: AWS::ApiGateway::RestApi
    Properties:
      Name: !Ref AWS::StackName
      Description: Stripe webhook callback endpoints
      Tags:
        - Key: Project
          Value: Misc
        - Key: "prx:cloudformation:stack-name"
          Value: !Ref AWS::StackName
        - Key: "prx:cloudformation:stack-id"
          Value: !Ref AWS::StackId
  RestApiWebhooksResource:
    Type: AWS::ApiGateway::Resource
    Properties:
      RestApiId: !Ref RestApi
      ParentId: !GetAtt RestApi.RootResourceId
      PathPart: webhooks
  RestApiWebhooksPostMethod:
    Type: AWS::ApiGateway::Method
    Properties:
      AuthorizationType: NONE
      HttpMethod: POST
      Integration:
        IntegrationHttpMethod: POST
        Type: AWS_PROXY
        Uri: !Sub arn:aws:apigateway:${AWS::Region}:lambda:path/2015-03-31/functions/${LambdaFunction.Arn}/invocations
      RestApiId: !Ref RestApi
      ResourceId: !Ref RestApiWebhooksResource
  RestApiDeployment:
    DependsOn:
      - RestApiWebhooksPostMethod
    Type: AWS::ApiGateway::Deployment
    Properties:
      RestApiId: !Ref RestApi
  RestApiStage:
    Type: AWS::ApiGateway::Stage
    Properties:
      StageName: prod
      Description: Production API
      RestApiId: !Ref RestApi
      DeploymentId: !Ref RestApiDeployment
  # Integration
  LambdaIamRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: "2012-10-17"
        Statement:
          - Effect: Allow
            Principal:
              Service:
                - lambda.amazonaws.com
            Action:
              - sts:AssumeRole
      Path: "/"
      Policies:
        - PolicyName: SnsPolicy
          PolicyDocument:
            Version: "2012-10-17"
            Statement:
              - Effect: Allow
                Action:
                  - sns:Publish
                Resource:
                  - !Ref SlackMessageRelayTopicArn
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Tags:
        - Key: Project
          Value: Misc
        - Key: "prx:cloudformation:stack-name"
          Value: !Ref AWS::StackName
        - Key: "prx:cloudformation:stack-id"
          Value: !Ref AWS::StackId
  LambdaFunction:
    Type: AWS::Lambda::Function
    Properties:
      Code:
        ZipFile: |
          const https = require('https');
          const { SNS } = require('@aws-sdk/client-sns');
          const url = require('url');

          const sns = new AWS.SNS({ apiVersion: '2010-03-31' });
          const sns = new SNS({
              apiVersion: '2010-03-31',
              region: process.env.SLACK_MESSAGE_RELAY_SNS_TOPIC_ARN.split(':')[3]
          });

          const SLACK_CHANNEL = '#garage-registration';
          const SLACK_USERNAME = 'Squarespace';
          const SLACK_ICON = ':squarespace:';

          function httpGet(reqUrl) {
              return new Promise((resolve, reject) => {
                  // Setup request options
                  const options = url.parse(reqUrl);
                  options.method = 'GET';
                  options.headers = {
                      'Authorization': `Bearer ${process.env.SQUARESPACE_API_TOKEN}`,
                      'User-Agent': 'PRX/1.0.0 (AWS Lambda/Node)',
                  };

                  // Request with response handler
                  const req = https.request(options, (res) => {
                      res.setEncoding('utf8');

                      let json = '';
                      res.on('data', (chunk) => { json += chunk; });
                      res.on('end', () => {
                          try {

                              const resPayload = JSON.parse(json);
                              resolve(resPayload);
                          } catch (e) {
                              console.error('Error handling JSON response!');
                              reject(e);
                          }
                      });
                  });

                  // Generic request error handling
                  req.on('error', e => reject(e));

                  req.end();
              });
          }

          async function getOrder(orderId) {
              console.info(`Getting Sqsqp order ${orderId}`);
              const orderUrl = `https://api.squarespace.com/1.0/commerce/orders/${orderId}`;
              const order = await httpGet(orderUrl);
              return order;
          }

          async function getAllInventory(cursor) {
              console.info(`Getting Sqsqp inventory ${cursor}`);
              const param = cursor ? `?cursor=${cursor}` : '';
              const inventoryUrl = `https://api.squarespace.com/1.0/commerce/inventory${param}`;

              const response = await httpGet(inventoryUrl);

              if (response.pagination.hasNextPage) {
                  console.log(`Paging ${response.pagination.nextPageCursor}`);
                  const more = await getAllInventory(response.pagination.nextPageCursor);
                  response.inventory.push(...more.inventory);
              }

              return response;
          }

          async function getInventory(variantId1) {
              console.info(`Getting Sqsqp inventory ${variantId1}`);
              const inventoryUrl = `https://api.squarespace.com/1.0/commerce/inventory/${variantId1}`;
              const inventory = await httpGet(inventoryUrl);
              return inventory.inventory[0];
          }

          exports.handler = async (event) => {
              try {
                  const stripePayload = JSON.parse(event.body);

                  const sqspOrderId = stripePayload.data.object.metadata.id;
                  const order = await getOrder(sqspOrderId);
                  const allInventory = await getAllInventory();

                  for (const lineItem of order.lineItems) {
                      const variant = allInventory.inventory.find(i => i.sku === lineItem.sku);
                      const inventory = await getInventory(variant.variantId);

                      await sns.publish({
                          TopicArn: process.env.SLACK_MESSAGE_RELAY_SNS_TOPIC_ARN,
                          Message: JSON.stringify({
                              channel: SLACK_CHANNEL,
                              username: SLACK_USERNAME,
                              icon_emoji: SLACK_ICON,
                              text: [
                                  `<mailto:${order.customerEmail}|${order.billingAddress.firstName} ${order.billingAddress.lastName}> ordered ${lineItem.quantity} ticket${lineItem.quantity === 1 ? '' : 's' } for *${inventory.descriptor}*`,
                              ].join('\n')
                          }),
                      });
                  }

                  return { statusCode: 200, headers: {}, body: '' };
              } catch (e) {
                  console.error(e);
                  return { statusCode: 200, headers: {}, body: '' };
              }
          };
      Description: Backs Stripe/Squarespace webhook API Gateway
      Environment:
        Variables:
          STRIPE_WEBHOOK_SIGNING_SECRET: !Ref StripeWebhookSigningSecret
          SLACK_MESSAGE_RELAY_SNS_TOPIC_ARN: !Ref SlackMessageRelayTopicArn
          SQUARESPACE_API_TOKEN: !Ref SquarespaceApiToken
      Handler: index.handler
      MemorySize: 128
      Role: !GetAtt LambdaIamRole.Arn
      Runtime: nodejs24.x
      Tags:
        - Key: Project
          Value: Misc
        - Key: "prx:cloudformation:stack-name"
          Value: !Ref AWS::StackName
        - Key: "prx:cloudformation:stack-id"
          Value: !Ref AWS::StackId
      Timeout: 8
  RestApiLambdaPermission:
    Type: AWS::Lambda::Permission
    Properties:
      Action: lambda:InvokeFunction
      FunctionName: !Ref LambdaFunction
      Principal: apigateway.amazonaws.com
      SourceArn: !Sub "arn:aws:execute-api:${AWS::Region}:${AWS::AccountId}:${RestApi}/${RestApiStage}/*"
  LambdaErrorAlarm:
    Type: AWS::CloudWatch::Alarm
    Properties:
      AlarmName: !Sub ERROR [Squarespace] Commerce webhook <prod> INVOCATION ERRORS (${AWS::StackName})
      AlarmDescription: The error rate on the Squarespace sales lambda has exceeded 0
      ComparisonOperator: GreaterThanThreshold
      EvaluationPeriods: 1
      MetricName: Errors
      Namespace: AWS/Lambda
      Period: 60
      Statistic: Sum
      Threshold: 0
      TreatMissingData: notBreaching
      Dimensions:
        - Name: FunctionName
          Value: !Ref LambdaFunction
  LambdaFunctionLogGroup:
    Type: AWS::Logs::LogGroup
    Properties:
      LogGroupName: !Sub /aws/lambda/${LambdaFunction}
      RetentionInDays: 5
